from pathlib import Path
import json
R=Path(__file__).resolve().parent
def inspect(id,label): return f'<button class="inspect" data-object="{id}">{label} <span aria-hidden="true">↗</span></button>'
source=f'''<section class="source artifact" data-node="source"><div class="eyebrow">01 / Source · synthetic</div><h2>What the client said</h2><div class="transcript"><span class="line-no">14</span><div><span class="speaker">CLIENT</span><blockquote>“I sold my company<br>in 2024.”</blockquote></div></div><div class="absence"><span>Not stated in this passage</span><p>Sale proceeds · corroboration · source date</p></div>{inspect('SOURCE-L14','Inspect the complete supplied passage')}<footer>One invented line. No additional transcript is available.</footer></section>'''
instruction=f'''<section class="instruction artifact" data-node="instruction"><div class="eyebrow">02 / Instruction · INS-01@1</div><h3>Preserve the statement.<br>Keep the gaps.</h3><p>Retain the event and its source. Do not infer an amount, verification or plausibility conclusion.</p>{inspect('INS-01@1','Read scope & version')}</section>'''
context=f'''<section class="context artifact" data-node="context"><div class="eyebrow">03 / Context · reported FenX reference</div><div class="field-tree"><div>Natural-person client <span>subject</span></div><div class="tree-child">Source of wealth</div><div class="tree-leaf">Significant event <span>candidate field</span></div></div><code>sourceOfWealthSignificantEvent</code><p class="context-normal">The category lookup for <code>individualSourceOfWealth</code> is not supplied. No category is selected.</p><p class="context-missing" hidden>Field meaning removed: retain the statement as unstructured context; the proposed field mapping is withheld.</p>{inspect('CTX-FENX@2026-08-18','Inspect subject & field distinctions')}</section>'''
method=f'''<section class="method artifact" data-node="method"><div class="eyebrow">04 / Method · METHOD-01@1</div><ol><li><b>Identify</b> the client and stated event</li><li><b>Map cautiously</b> using field meaning</li><li><b>Cite</b> line 14</li><li><b>Expose</b> missing information</li></ol>{inspect('METHOD-01@1','Inspect inputs & failure modes')}</section>'''
output=f'''<section class="output artifact" data-node="output"><div class="eyebrow">05 / AI-prepared output · OBS-01@1</div><span class="status">Candidate · for colleague review</span><h2>Client states that they sold<br>their company in 2024.</h2><div class="output-field"><span>Candidate event field</span><code class="mapped-field">sourceOfWealthSignificantEvent</code><strong class="unmapped-field" hidden>Mapping withheld — field context missing</strong></div><dl class="output-values"><div><dt>Source pointer</dt><dd><button class="source-link" data-object="SOURCE-L14">CLIENT [14] ↗</button></dd></div><div><dt>Amount</dt><dd class="unresolved">Unresolved</dd></div><div><dt>Corroboration</dt><dd class="unresolved">Not supplied</dd></div><div><dt>Verification / plausibility</dt><dd>Not inferred</dd></div></dl>{inspect('OBS-01@1','Inspect preparation & reported schema')}<footer>No customer assessment. No write to a FenX record.</footer></section>'''
review=f'''<section class="review artifact" data-node="review"><div class="eyebrow">06 / Human review</div><h3>Is this faithful<br>to the source?</h3><ul class="review-checks"><li>Correct client and event?</li><li>Source supports every statement?</li><li>Missing facts still visible?</li><li>Field mapping appropriate?</li></ul><div class="decision"><span>Task disposition · demonstration only</span><button data-review="needs-work" aria-pressed="false">Needs more work</button><button data-review="prepared" aria-pressed="false">Accept preparation only</button><p data-review-status role="status">No review decision recorded.</p></div>{inspect('REUSE-01@1','Why reuse needs a separate review')}</section>'''
requirement=f'''<section class="requirement artifact" data-node="requirement"><div class="eyebrow">Development counterpart · REQ-01@1</div><h3>Make absence testable.</h3><p><b>Given</b> an event without an amount,<br><b>retain</b> the event and source;<br><b>leave</b> the amount unresolved.</p>{inspect('REQ-01@1','Inspect requirement & mapping')}</section>'''
test=f'''<section class="test artifact" data-node="test"><div class="eyebrow">Acceptance case · TEST-01@1</div><h3>Challenge an invented amount.</h3><p><b>Fixture:</b> line 14 has no proceeds.<br><b>Expected:</b> no fabricated amount.<br><b>Also challenge:</b> wrong subject and unsupported verification.</p>{inspect('TEST-01@1','Inspect fixture & negative cases')}</section>'''
evidence=f'''<section class="evidence artifact" data-node="evidence"><div class="eyebrow">07 / Evidence · EVID-01@1</div><h3>No observed run supplied.</h3><dl><div><dt>Scope</dt><dd>INS-01@1 · REQ-01@1 · TEST-01@1</dd></div><div><dt>Implementation / run / result</dt><dd>Not supplied</dd></div></dl>{inspect('EVID-01@1','Inspect evidence record')}</section>'''
condition='''<div class="conditions"><div><b>What can work now</b><span>Preparation from supplied material; no live interface is required.</span></div><label><input type="checkbox" data-context-toggle checked> Include reported FenX field context</label><div><b>What this does not establish</b><span>Live retrieval, record writes, a shared runtime or permission to operate.</span></div></div>'''
reuse='''<div class="reuse"><b>Useful in this task ≠ approved for reuse</b><span>Selected instructions, context and methods may support another task after applicability, ownership, maintenance and permitted consumption are established.</span></div>'''
parts=dict(source=source,instruction=instruction,context=context,method=method,output=output,review=review,requirement=requirement,test=test,evidence=evidence)
nav='''<header class="top"><a href="../../">CLM AI <span>Knowledge Hub</span></a><span class="section-name">Useful work first</span><nav aria-label="Composition alternatives"><a href="../direction-a/">A · Workbench</a><a href="../direction-b/">B · Case folio</a><a href="../direction-c/">C · Trace ledger</a></nav><span class="prototype">Design study · not production</span></header>'''
intro='''<div class="intro"><div><div class="eyebrow">Run CLM / One synthetic preparation task</div><h1>From a client statement<br>to a reviewable observation.</h1></div><div class="intro-right"><p>AI can prepare useful CLM work when the source, instruction, field meaning and method travel together.</p><span>Read the artifacts. Inspect any underlined label for its exact scope.</span></div></div>'''
chain='''<div class="chain" aria-label="Explanation sequence"><span>Source</span><i>constrained by</i><span>Instruction</span><i>interpreted using</i><span>Context</span><i>applied through</i><span>Method</span><i>prepares</i><span>Output</span><i>requires</i><span>Review</span><i>distinct from</i><span>Test evidence</span></div>'''
# Independent structures. Shared artifact semantics, not merely reskinned layouts.
a=f'''<div class="workbench"><div class="inputs">{source}<div class="input-foot">{instruction}{context}</div></div><div class="preparation">{method}{output}</div><div class="accountability">{review}{evidence}</div></div><div class="development"><div class="dev-label"><span class="eyebrow">The same instruction also guides development</span><h3>Specify it.<br>Challenge it.</h3></div>{requirement}{test}</div>'''
b=f'''<div class="folio"><div class="folio-source">{source}{context}</div><div class="folio-center"><div class="folio-annotations">{instruction}{method}</div>{output}<div class="folio-bottom">{requirement}{test}</div></div><aside class="folio-margin">{review}{evidence}</aside></div>'''
# C is a precise argument ledger, each row follows one proposition across source/context/output/control.
c=f'''<div class="ledger-top">{source}{instruction}{method}</div><div class="trace-ledger"><div class="ledger-head"><span>Source / relevant meaning</span><span>Prepared observation</span><span>Human review / development check</span></div><div class="ledger-row"><div><span class="eyebrow">The stated event</span><h3>“I sold my company in 2024.”</h3>{inspect('SOURCE-L14','CLIENT [14]')}</div><div><span class="eyebrow">Candidate description</span><h3>Client states a company sale in 2024.</h3>{inspect('OBS-01@1','OBS-01@1')}</div><div><h3>Check the subject and source fidelity.</h3><p>No verification or plausibility conclusion follows from a statement.</p></div></div><div class="ledger-row"><div>{context}</div><div class="mapped-field"><span class="eyebrow">Candidate event field</span><code>sourceOfWealthSignificantEvent</code><p>Category remains unresolved.</p></div><div class="unmapped-field" hidden><h3>Mapping withheld</h3><p>Field context is missing.</p></div><div>{requirement}</div></div><div class="ledger-row"><div><span class="eyebrow">The missing amount</span><h3>No proceeds stated.</h3><p>The passage supplies no amount or corroboration.</p></div><div><span class="eyebrow">Output boundary</span><h3>Amount: unresolved.</h3><p>Supporting evidence: not supplied.</p></div><div>{test}</div></div></div><div class="ledger-bottom">{review}{evidence}</div>'''
for d,body in [('a',a),('b',b),('c',c)]:
 p=R/f'direction-{d}';p.mkdir(parents=True,exist_ok=True)
 p.joinpath('index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Useful work first · {d.upper()} · CLM AI Knowledge Hub</title><link rel="stylesheet" href="../shared/useful.css"><script src="../shared/objects.js" defer></script><script src="../shared/useful.js" defer></script></head><body class="architecture-{d}">{nav}<main>{intro}{chain}{body}{condition}{reuse}</main><footer class="page-footer"><span>Synthetic teaching case · field context is source-reported, not verified current production.</span><span>SEB Sans Serif requested; approved font binary not supplied. System fallback shown.</span></footer><dialog aria-labelledby="detail-title"><div class="dialog-top"><span>Object inspection</span><button data-close aria-label="Close inspection">Close ×</button></div><div id="detail-body"></div></dialog></body></html>''')
R.joinpath('shared/parts.json').write_text(json.dumps(parts,indent=2))
